-- Tracks a vestigial table on the authnd-production cluster.  Not used for dev/test/CI.
CREATE TABLE `user_sessions` (
  `id` bigint unsigned NOT NULL,
  `user_id` bigint unsigned NOT NULL,
  `ip` varchar(60) DEFAULT NULL,
  `time_zone_name` varchar(60) DEFAULT NULL,
  `user_agent` text,
  `accessed_at` datetime NOT NULL,
  `created_at` datetime NOT NULL,
  `impersonator_id` bigint unsigned DEFAULT NULL,
  `revoked_at` datetime DEFAULT NULL,
  `impersonator_session_id` bigint unsigned DEFAULT NULL,
  `sudo_enabled_at` datetime DEFAULT NULL,
  `hashed_key` varbinary(44) NOT NULL,
  `csrf_token` varbinary(44) NOT NULL,
  `revoked_reason` varchar(50) DEFAULT NULL,
  `secret` varbinary(44) DEFAULT NULL,
  `hashed_private_mode_key` varbinary(44) DEFAULT NULL,
  `hashed_gist_key` varbinary(44) DEFAULT NULL,
  `expires_at` datetime(6) DEFAULT NULL,
  `sync_timestamp` datetime NOT NULL,
  `sync_kafka_offset` bigint(20) NOT NULL,
  `sync_binlog_position` varchar(255) NOT NULL,
  `sync_gtid_position` varchar(255) NOT NULL,
  `sync_state` int(11) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `index_user_sessions_on_hashed_key` (`hashed_key`),
  UNIQUE KEY `index_user_sessions_on_hashed_private_mode_key` (`hashed_private_mode_key`),
  UNIQUE KEY `index_user_sessions_on_hashed_gist_key` (`hashed_gist_key`),
  KEY `index_user_sessions_on_accessed_at` (`accessed_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
